def solve(nums):
    # Return the next lexicographic permutation of the list nums.
    # If nums is empty or has one element, return a copy of it.
    if len(nums) <= 1:
        return list(nums)
    arr = list(nums)  # work on a copy
    n = len(arr)
    # Find the first index i from the end where arr[i] < arr[i+1]
    i = n - 2
    while i >= 0 and arr[i] >= arr[i + 1]:
        i -= 1
    if i == -1:
        # Already the highest permutation
        return sorted(arr)
    # Find the smallest element greater than arr[i] to the right
    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1
    # Swap them
    arr[i], arr[j] = arr[j], arr[i]
    # Reverse the suffix starting at i+1
    arr[i + 1:] = reversed(arr[i + 1:])
    return arr

