    """Balanced brackets check that tolerates non‑iterable inputs.
    Returns True if the brackets are properly nested; for inputs that cannot be
    iterated over (e.g., None, int) it treats them as containing no brackets.
    """
    try:
        iterator = iter(s)
    except TypeError:
        return True
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    opening = set(pairs.values())
    closing = set(pairs.keys())
    for ch in iterator:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

